    body: "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 32 32\"><title>Mailroom</title><style>path{fill:#0A0A0A}@media(prefers-color-scheme:dark){path{fill:#EDEDED}}</style><path fill-rule=\"evenodd\" d=\"M8 0h16a8 8 0 0 1 8 8v16a8 8 0 0 1-8 8H8a8 8 0 0 1-8-8V8a8 8 0 0 1 8-8z M7 10.5a1.5 1.5 0 0 1 2.3-1.27L16 13.4l6.7-4.17A1.5 1.5 0 0 1 25 10.5v11a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 7 21.5z\"/></svg>\n",
